53	/** Base implementation of {@link FileMergingSnapshotManager}. */
54	public abstract class FileMergingSnapshotManagerBase implements FileMergingSnapshotManager {
55	
56	    private static final Logger LOG = LoggerFactory.getLogger(FileMergingSnapshotManager.class);
57	
58	    /** The identifier of this manager. */
59	    private final String id;
60	
61	    /** The executor for I/O operations in this manager. */
62	    protected final Executor ioExecutor;
63	
64	    /** Guard for uploadedStates. */
65	    protected final Object lock = new Object();
66	
67	    @GuardedBy("lock")
68	    protected TreeMap<Long, Set<LogicalFile>> uploadedStates = new TreeMap<>();
69	
70	    /** The {@link FileSystem} that this manager works on. */
71	    protected FileSystem fs;
72	
73	    // checkpoint directories
74	    protected Path checkpointDir;
75	    protected Path sharedStateDir;
76	    protected Path taskOwnedStateDir;
77	
78	    /** The buffer size for writing files to the file system. */
79	    protected int writeBufferSize;
80	
81	    /**
82	     * The file system should only be initialized once.
83	     *
84	     * @see FileMergingSnapshotManager#initFileSystem for the reason why a throttle is needed.
85	     */
86	    private boolean fileSystemInitiated = false;
87	
88	    /**
89	     * File-system dependent value. Mark whether the file system this manager running on need sync
90	     * for visibility. If true, DO a file sync after writing each segment .
91	     */
92	    protected boolean shouldSyncAfterClosingLogicalFile;
93	
94	    /** Max size for a physical file. */
95	    protected long maxPhysicalFileSize;
96	
97	    /** Type of physical file pool. */
98	    protected PhysicalFilePool.Type filePoolType;
99	
100	    protected PhysicalFileDeleter physicalFileDeleter = this::deletePhysicalFile;
101	
102	    /**
103	     * Currently the shared state files are merged within each subtask, files are split by different
104	     * directories.
105	     */
106	    private final Map<SubtaskKey, Path> managedSharedStateDir = new ConcurrentHashMap<>();
107	
108	    /**
109	     * The private state files are merged across subtasks, there is only one directory for
110	     * merged-files within one TM per job.
111	     */
112	    protected Path managedExclusiveStateDir;
113	
