119	        this.ioExecutor = ioExecutor;
120	    }
121	
122	    @Override
123	    public void initFileSystem(
124	            FileSystem fileSystem,
125	            Path checkpointBaseDir,
126	            Path sharedStateDir,
127	            Path taskOwnedStateDir,
128	            int writeBufferSize)
129	            throws IllegalArgumentException {
