19	package org.apache.flink.runtime.state;
20	
21	import org.apache.flink.util.FileUtils;
22	
23	import javax.annotation.Nonnull;
24	
25	import java.io.IOException;
26	import java.nio.file.Path;
27	import java.nio.file.Paths;
28	
29	/**
30	 * This state handle represents a directory. This class is, for example, used to represent the
31	 * directory of RocksDB's native checkpoint directories for local recovery.
32	 */
33	public class DirectoryStateHandle implements StateObject {
34	
35	    /** Serial version. */
36	    private static final long serialVersionUID = 1L;
37	
38	    /** The path that describes the directory, as a string, to be serializable. */
39	    private final String directoryString;
40	
41	    /** (Optional) Size of the directory, used for metrics. Can be 0 if unknown or empty. */
42	    private final long directorySize;
43	
44	    /** Transient path cache, to avoid re-parsing the string. */
45	    private transient Path directory;
46	
47	    public DirectoryStateHandle(@Nonnull Path directory, long directorySize) {
48	        this.directory = directory;
49	        this.directoryString = directory.toString();
50	        this.directorySize = directorySize;
51	    }
52	
53	    public static DirectoryStateHandle forPathWithSize(@Nonnull Path directory) {
54	        long size;
55	        try {
56	            size = FileUtils.getDirectoryFilesSize(directory);
57	        } catch (IOException e) {
58	            size = 0L;
59	        }
60	        return new DirectoryStateHandle(directory, size);
61	    }
62	
63	    @Override
64	    public void discardState() throws IOException {
65	        ensurePath();
66	        FileUtils.deleteDirectory(directory.toFile());
67	    }
68	
69	    @Override
70	    public long getStateSize() {
71	        return directorySize;
72	    }
73	
74	    @Override
75	    public void collectSizeStats(StateObjectSizeStatsCollector collector) {
76	        collector.add(StateObjectLocation.LOCAL_DISK, directorySize);
77	    }
78	
79	    @Nonnull
80	    public Path getDirectory() {
81	        ensurePath();
82	        return directory;
83	    }
84	
85	    private void ensurePath() {
86	        if (directory == null) {
87	            directory = Paths.get(directoryString);
88	        }
89	    }
90	
91	    @Override
92	    public boolean equals(Object o) {
93	        if (this == o) {
94	            return true;
95	        }
96	        if (o == null || getClass() != o.getClass()) {
97	            return false;
98	        }
99	
100	        DirectoryStateHandle that = (DirectoryStateHandle) o;
101	
102	        return directoryString.equals(that.directoryString);
103	    }
104	
105	    @Override
106	    public int hashCode() {
107	        return directoryString.hashCode();
108	    }
109	
110	    @Override
111	    public String toString() {
112	        return "DirectoryStateHandle{"
113	                + "directory='"
114	                + directoryString
115	                + '\''
116	                + ", directorySize="
117	                + directorySize
118	                + '}';
119	    }
120	}
