28	/**
29	 * State handle for partitionable operator state. Besides being a {@link StreamStateHandle}, this
30	 * also provides a map that contains the offsets to the partitions of named states in the stream.
31	 */
32	public class OperatorStreamStateHandle implements OperatorStateHandle {
33	
34	    private static final long serialVersionUID = 35876522969227335L;
35	
36	    /** unique state name -> offsets for available partitions in the handle stream */
37	    private final Map<String, StateMetaInfo> stateNameToPartitionOffsets;
38	
39	    private final StreamStateHandle delegateStateHandle;
40	
41	    public OperatorStreamStateHandle(
42	            Map<String, StateMetaInfo> stateNameToPartitionOffsets,
43	            StreamStateHandle delegateStateHandle) {
44	
45	        this.delegateStateHandle = Preconditions.checkNotNull(delegateStateHandle);
46	        this.stateNameToPartitionOffsets = Preconditions.checkNotNull(stateNameToPartitionOffsets);
47	    }
48	
49	    @Override
50	    public Map<String, StateMetaInfo> getStateNameToPartitionOffsets() {
51	        return stateNameToPartitionOffsets;
52	    }
53	
54	    @Override
55	    public void discardState() throws Exception {
56	        delegateStateHandle.discardState();
57	    }
58	
59	    @Override
60	    public long getStateSize() {
61	        return delegateStateHandle.getStateSize();
62	    }
63	
64	    @Override
65	    public void collectSizeStats(StateObjectSizeStatsCollector collector) {
66	        delegateStateHandle.collectSizeStats(collector);
67	    }
68	
69	    @Override
70	    public FSDataInputStream openInputStream() throws IOException {
71	        return delegateStateHandle.openInputStream();
72	    }
73	
74	    @Override
75	    public Optional<byte[]> asBytesIfInMemory() {
76	        return delegateStateHandle.asBytesIfInMemory();
77	    }
78	
79	    @Override
80	    public PhysicalStateHandleID getStreamStateHandleID() {
81	        return delegateStateHandle.getStreamStateHandleID();
82	    }
83	
84	    @Override
85	    public StreamStateHandle getDelegateStateHandle() {
86	        return delegateStateHandle;
87	    }
88	
89	    @Override
90	    public boolean equals(Object o) {
91	        if (this == o) {
92	            return true;
93	        }
94	
95	        if (!(o instanceof OperatorStreamStateHandle)) {
96	            return false;
97	        }
98	
99	        OperatorStreamStateHandle that = (OperatorStreamStateHandle) o;
100	
101	        if (stateNameToPartitionOffsets.size() != that.stateNameToPartitionOffsets.size()) {
102	            return false;
103	        }
104	
105	        for (Map.Entry<String, StateMetaInfo> entry : stateNameToPartitionOffsets.entrySet()) {
106	            if (!entry.getValue().equals(that.stateNameToPartitionOffsets.get(entry.getKey()))) {
107	                return false;
108	            }
109	        }
110	
111	        return delegateStateHandle.equals(that.delegateStateHandle);
112	    }
113	
114	    @Override
115	    public int hashCode() {
116	        int result = delegateStateHandle.hashCode();
117	        for (Map.Entry<String, StateMetaInfo> entry : stateNameToPartitionOffsets.entrySet()) {
118	
119	            int entryHash = entry.getKey().hashCode();
120	            if (entry.getValue() != null) {
121	                entryHash += entry.getValue().hashCode();
122	            }
123	            result = 31 * result + entryHash;
124	        }
125	        return result;
126	    }
